import CrackscreenSuccess from './Crackscreen'
import GenericSuccess from './Generic'

// const { resetDetails } = lifeActions;
class PaymentMapper extends Component {
  state = {
    component: null
  }

  componentDidMount() {
    const searchParams = new URLSearchParams(this.props.location.search)
    const product = searchParams.get('product')
    let component = null

    switch (product) {
      case 'crack-screen-protection-plus':
        component = CrackscreenSuccess
        break
      default:
        component = GenericSuccess
        break
    }

    this.setState({
      component
    })

    // window.scrollTo(0, 0);
  }

  render() {
    const { state = {} } = this.props.location
    const { params } = state
    const {
      component: Component
    } = this.state

    return (
      <React.Fragment>
        {Component ? (
          <Component {...this.props} />
        ) : (
          'Loading'
        )}
      </React.Fragment>
    )
  }
}

export default PaymentMapper
