import React, { Component } from 'react'
import { connect } from 'react-redux'
import SuccessWrapper from './index.style'
import { Button, Row, Col, Card } from 'antd'
import SuccessFemale from '../../../../../image/female.png'
import { persistor } from '../../../../../redux/store'

class Payment extends Component {
  state = {
    applicationId: null,
    email: null
  }

  goHome = () => {
    persistor.purge()
    window.location.href = window.location.origin
  }

  componentDidMount () {
    window.scrollTo(0, 0)
    if (!this.props.location.state) {
      this.goHome()
    }

    const searchParams = new URLSearchParams(this.props.location.search)
    const applicationId = searchParams.get('applicationId')
    const email = searchParams.get('email')
    this.setState({
      applicationId,
      email
    })
  }
  componentWillUnmount = async () => {
    await persistor.purge()
  }

  render () {
    const { params } = this.props.location.state
    const { applicationId, email } = this.state
    return (
      <SuccessWrapper>
        <Row type='flex' justify='center'>
          <Col xs={24} sm={24} md={17} lg={16} xl={16}>
            <Card>
              <Row type='flex' justify='center' className='component-card'>
                <Col span={16}>
                  <h3 className='mb-30'>Pembayaran Berhasil</h3>
                  <p className='mb-10'>Pembayaran Anda akan segera di proses.</p>
                  <p className='mb-30'>Kami akan memberi kabar bila polis Anda sudah siap.</p>
                  <div className='mb-30'>
                    <p>
                      Nomor Booking Anda:
                      <b style={{ display: 'block' }}>
                        {applicationId || params.appID}
                      </b>
                    </p>
                    <p>
                      Email Akan Dikirim Ke: <br />
                      <span>
                        {email || params.email}
                      </span>
                    </p>
                    <p>
                      <a href={`${process.env.REACT_APP_POLICIES_LINK}`} className='text-underline'>
                        Klik disini
                      </a>
                      {' '}untuk melihat polis Anda
                    </p>
                  </div>
                  <Button className='button-primary' onClick={this.goHome}>KEMBALI KE BERANDA</Button>
                </Col>
                <Col span={8}>
                  <img src={SuccessFemale} alt='payment-success' className='payment-image' />
                </Col>
              </Row>
            </Card>
          </Col>
        </Row>
      </SuccessWrapper>
    )
  }
}

export default connect(
  state => ({
    // ...state
  }),
  {
    // resetDetails
  }
)(Payment)
